// ΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉ
//  ERL ΓåÆ IRL LIQUIDITY ENGINE v2.1
//  Next Level Foundry
//
//  v2.1 PATCHES:
//   ┬╖ inBwDZone now waits for an actual post-break retrace
//   ┬╖ CONTINUATION targets extension high/low, not the broken (flipped) level
//   ┬╖ BwD now locks the sweep level so it can't double-fire as a sweep marker
//   ┬╖ PDH/PDL score uses the live event level for its side only
//   ┬╖ Mode has explicit WAIT branch when no events have occurred
//   ┬╖ Flipped level auto-clears after staleness / distance
//   ┬╖ Zone-entry + score-crosses-75 alerts are edge-triggered (no repeats)
//   ┬╖ Removed dead bwdZoneStart variable
//
//  WHAT THIS DOES:
//   Tracks the complete lifecycle of a liquidity range from two angles:
//
//   SCENARIO A ΓÇö SWEEP & REVERSE
//     Wick pierces ERL/PDH/PDL ΓåÆ closes back inside ΓåÆ reversal ΓåÆ draw to IRL
//     Stops were grabbed, liquidity consumed, price reverses
//
//   SCENARIO B ΓÇö BREAK WITH DISPLACEMENT (BwD)
//     Full body candle closes THROUGH ERL/PDH/PDL ΓåÆ continuation expected
//     Broken level FLIPS (resistance ΓåÆ support or vice versa)
//     Displacement candle body becomes the entry zone on retrace
//     New ERL forms above/below to become next draw target
//
//   PDH/PDL act as premium ERL levels ΓÇö highest probability sweep/BwD zones
//   Session filter weights London + NY setups higher in confidence score
// ΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉ

//@version=6
indicator("ERL ΓåÆ IRL Engine v2 [NLF]", "ERLΓåÆIRL", overlay = true,
     max_lines_count  = 500,
     max_labels_count = 500,
     max_boxes_count  = 500,
     max_bars_back    = 1000)

// ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
//  INPUTS
// ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
gRange      = "Γû╕ RANGE DETECTION"
swingLen    = input.int(15,   "Swing Strength (bars each side)", minval = 3,  group = gRange,
                 tooltip = "Higher = larger, more significant pivots only.")
maxLookback = input.int(300,  "Max Lookback (bars)",             minval = 50, group = gRange)

gPD         = "Γû╕ PREVIOUS DAY HIGH / LOW"
showPD      = input.bool(true, "Show PDH / PDL",                               group = gPD)
pdLabel     = input.bool(true, "Show PDH/PDL Labels",                          group = gPD)

gBwD        = "Γû╕ BREAK WITH DISPLACEMENT"
bwdATRMult  = input.float(1.2, "Min Body Size (├ù ATR)",    minval = 0.3, step = 0.1, group = gBwD,
                 tooltip = "Body must be this multiple of ATR to qualify as displacement.")
bwdBodyPct  = input.int(55,    "Min Body % of Candle",     minval = 30,  maxval = 90, group = gBwD,
                 tooltip = "Body/candle-range ratio. Filters doji-like candles.")
showBwDZone = input.bool(true, "Show Displacement Zone",                       group = gBwD)
showFlipped = input.bool(true, "Show Flipped Level",                           group = gBwD)
bwdZoneExt  = input.int(40,    "Extend Displacement Zone (bars)", minval = 5,  group = gBwD)

gSweep      = "Γû╕ SWEEP LOGIC"
sweepCool   = input.int(20,  "Sweep Cooldown (bars)", minval = 0, group = gSweep,
                 tooltip = "Min bars between sweep markers on the same side.")
sweepLock   = input.bool(true, "Lock Sweep to Level",              group = gSweep,
                 tooltip = "Prevents the same ERL level being swept repeatedly until a new pivot forms.")

gFVG        = "Γû╕ IRL INEFFICIENCIES (FVG)"
fvgOn       = input.bool(true,  "Detect Inefficiencies",           group = gFVG)
fvgMinATR   = input.float(0.4,  "Min Size (├ù ATR)", minval = 0.1, step = 0.1, group = gFVG)
fvgMax      = input.int(8,      "Max Active FVGs",  minval = 1,                group = gFVG)

gSession    = "Γû╕ SESSION FILTER"
sessionOn   = input.bool(true,               "Apply Session Scoring",       group = gSession)
sessionTZ   = input.string("America/New_York", "Chart Timezone",            group = gSession)

gVis        = "Γû╕ VISUALS"
showERL     = input.bool(true, "Show ERL Levels",         group = gVis)
showIRL     = input.bool(true, "Show IRL Equilibrium",    group = gVis)
showFVGVis  = input.bool(true, "Show IRL Inefficiencies", group = gVis)
showMarkers = input.bool(true, "Show Event Markers",      group = gVis)
showPanel   = input.bool(true, "Show Advisor Panel",      group = gVis)
extR        = input.int(25,    "Extend Lines Right",      minval = 5, group = gVis)

gClr        = "Γû╕ COLORS"
cERLHi      = input.color(#f87171, "ERL High (BSL)",         group = gClr)
cERLLo      = input.color(#4ade80, "ERL Low (SSL)",          group = gClr)
cIRL        = input.color(#22d3ee, "IRL Equilibrium",        group = gClr)
cFVGClr     = input.color(#a855f7, "IRL Inefficiency (FVG)", group = gClr)
cPDH        = input.color(#fb923c, "PDH",                    group = gClr)
cPDL        = input.color(#facc15, "PDL",                    group = gClr)
cBwDBull    = input.color(#4ade80, "BwD Bullish Zone",       group = gClr)
cBwDBear    = input.color(#f87171, "BwD Bearish Zone",       group = gClr)
cFlipClr    = input.color(#c084fc, "Flipped Level",          group = gClr)

// NLF brand constants
cPurple     = #a855f7
cCyan       = #22d3ee
cBgDeep     = #07060b
cBgPanel    = #100e1a
cBgRow      = #15132a
cTextPri    = #e8e4f0
cTextMute   = #9f97b8
cAmber      = #facc15
cGreen      = #4ade80
cRed        = #f87171
cDim        = #3d3a52

// ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
//  ATR + PRICE DATA
// ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
atr        = ta.atr(14)
bodySize   = math.abs(close - open)
candleRng  = high - low
bodyRatio  = candleRng > 0 ? bodySize / candleRng : 0.0

// ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
//  PDH / PDL  (previous day high / low)
// ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
pdh = request.security(syminfo.tickerid, "D", high[1], lookahead = barmerge.lookahead_on)
pdl = request.security(syminfo.tickerid, "D", low[1],  lookahead = barmerge.lookahead_on)

// Track day start bar for drawing PDH/PDL lines from today's open
var int dayStartBar = 0
if ta.change(time("D")) != 0
    dayStartBar := bar_index

// ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
//  SWING RANGE ΓÇö ERL HIGH / LOW
// ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
ph = ta.pivothigh(swingLen, swingLen)
pl = ta.pivotlow (swingLen, swingLen)

var array<float> phPx  = array.new<float>()
var array<int>   phBar = array.new<int>()
var array<float> plPx  = array.new<float>()
var array<int>   plBar = array.new<int>()

if not na(ph)
    array.push(phPx,  ph)
    array.push(phBar, bar_index - swingLen)
if not na(pl)
    array.push(plPx,  pl)
    array.push(plBar, bar_index - swingLen)

// prune beyond lookback
cutoff = bar_index - maxLookback
while array.size(phBar) > 0 and array.get(phBar, 0) < cutoff
    array.shift(phBar)
    array.shift(phPx)
while array.size(plBar) > 0 and array.get(plBar, 0) < cutoff
    array.shift(plBar)
    array.shift(plPx)

// highest swing high + lowest swing low = active ERL
float rangeHi    = na
int   rangeHiBar = na
float rangeLo    = na
int   rangeLoBar = na

if array.size(phPx) > 0
    for i = 0 to array.size(phPx) - 1
        v = array.get(phPx, i)
        if na(rangeHi) or v > rangeHi
            rangeHi    := v
            rangeHiBar := array.get(phBar, i)

if array.size(plPx) > 0
    for i = 0 to array.size(plPx) - 1
        v = array.get(plPx, i)
        if na(rangeLo) or v < rangeLo
            rangeLo    := v
            rangeLoBar := array.get(plBar, i)

eq = na(rangeHi) or na(rangeLo) ? na : (rangeHi + rangeLo) / 2.0

// ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
//  SESSION SCORING
//  London  03:00 ΓÇô 12:00 ET
//  New York 09:30 ΓÇô 16:00 ET
// ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
hh      = hour(time,   sessionTZ)
mm      = minute(time, sessionTZ)
tVal    = hh * 100 + mm

inLon   = tVal >=  300 and tVal < 1200
inNY    = tVal >=  930 and tVal < 1600
inSess  = inLon or inNY

// ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
//  SWEEP DETECTION
//  Wick through ERL or PDH/PDL, CLOSE back inside ΓåÆ stops grabbed ΓåÆ reversal
// ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
var string lastSweepType = "NONE"
var int    lastSweepBar  = na
var float  bslSweptLvl   = na
var float  sslSweptLvl   = na
var int    lastBSLBar    = na
var int    lastSSLBar    = na

// raw events
bslERL  = not na(rangeHi) and high >  rangeHi and close < rangeHi
sslERL  = not na(rangeLo) and low  <  rangeLo and close > rangeLo
bslPDH  = not na(pdh)     and high >  pdh     and close < pdh
sslPDL  = not na(pdl)     and low  <  pdl     and close > pdl

// quality filters
bslNewLvl = not sweepLock or na(bslSweptLvl) or (rangeHi != bslSweptLvl and pdh != bslSweptLvl)
sslNewLvl = not sweepLock or na(sslSweptLvl) or (rangeLo != sslSweptLvl and pdl != sslSweptLvl)
bslCool   = na(lastBSLBar) or bar_index - lastBSLBar >= sweepCool
sslCool   = na(lastSSLBar) or bar_index - lastSSLBar >= sweepCool

bslSweep  = (bslERL or bslPDH) and bslNewLvl and bslCool
sslSweep  = (sslERL or sslPDL) and sslNewLvl and sslCool

if bslSweep
    lastSweepType := "BSL"
    lastSweepBar  := bar_index
    bslSweptLvl   := bslPDH ? pdh : rangeHi
    lastBSLBar    := bar_index
if sslSweep
    lastSweepType := "SSL"
    lastSweepBar  := bar_index
    sslSweptLvl   := sslPDL ? pdl : rangeLo
    lastSSLBar    := bar_index

// ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
//  BREAK WITH DISPLACEMENT DETECTION
//  Full candle BODY closes through ERL/PDH/PDL with size + conviction
//
//  Bull BwD: body closes ABOVE level ΓåÆ continuation up, level flips to support
//  Bear BwD: body closes BELOW level ΓåÆ continuation down, level flips to resistance
// ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
bwdSizeOK = bodySize  >= atr * bwdATRMult
bwdBodyOK = bodyRatio >= bwdBodyPct / 100.0

// through ERL
bullBwD_ERL = not na(rangeHi) and close > rangeHi and open <= rangeHi and bwdSizeOK and bwdBodyOK
bearBwD_ERL = not na(rangeLo) and close < rangeLo and open >= rangeLo and bwdSizeOK and bwdBodyOK

// through PDH / PDL
bullBwD_PDH = not na(pdh) and close > pdh and open <= pdh and bwdSizeOK and bwdBodyOK
bearBwD_PDL = not na(pdl) and close < pdl and open >= pdl and bwdSizeOK and bwdBodyOK

bullBwD = (bullBwD_ERL or bullBwD_PDH) and not bearBwD_ERL and not bearBwD_PDL
bearBwD = (bearBwD_ERL or bearBwD_PDL) and not bullBwD_ERL and not bullBwD_PDH

var string lastBwDType  = "NONE"
var int    lastBwDBar   = na
var float  bwdZoneTop   = na
var float  bwdZoneBot   = na
var float  flippedLvl   = na
var bool   flippedBull  = false
var float  extensionHi  = na   // highest high since last bullish BwD
var float  extensionLo  = na   // lowest  low  since last bearish BwD

if bullBwD
    lastBwDType  := "BULL"
    lastBwDBar   := bar_index
    bwdZoneTop   := math.max(open, close)
    bwdZoneBot   := math.min(open, close)
    flippedLvl   := bullBwD_PDH ? pdh : rangeHi
    flippedBull  := true
    extensionHi  := high
    extensionLo  := na
    // lock this level so a wick back through doesn't re-fire as a BSL sweep
    bslSweptLvl  := bullBwD_PDH ? pdh : rangeHi
    lastBSLBar   := bar_index

if bearBwD
    lastBwDType  := "BEAR"
    lastBwDBar   := bar_index
    bwdZoneTop   := math.max(open, close)
    bwdZoneBot   := math.min(open, close)
    flippedLvl   := bearBwD_PDL ? pdl : rangeLo
    flippedBull  := false
    extensionLo  := low
    extensionHi  := na
    // lock this level so a wick back through doesn't re-fire as an SSL sweep
    sslSweptLvl  := bearBwD_PDL ? pdl : rangeLo
    lastSSLBar   := bar_index

// extend the extension extreme each bar in the active continuation direction
if lastBwDType == "BULL" and not na(extensionHi)
    extensionHi := math.max(extensionHi, high)
if lastBwDType == "BEAR" and not na(extensionLo)
    extensionLo := math.min(extensionLo, low)

// clear stale flipped level
//   ┬╖ 200+ bars have passed since the BwD without a retrace
//   ┬╖ OR price has moved more than 10 ATR away from it
if not na(flippedLvl) and not na(lastBwDBar)
    barsSinceFlip = bar_index - lastBwDBar
    farFromFlip   = math.abs(close - flippedLvl) > atr * 10
    if (barsSinceFlip > 200 and not inBwDZone) or farFromFlip
        flippedLvl  := na
        flippedBull := false

// is price retracing into the displacement zone?
// MUST be a bar AFTER the BwD bar ΓÇö the break candle itself doesn't count as a retrace
inBwDZone = lastBwDType != "NONE" and not na(bwdZoneTop) and not na(lastBwDBar) and bar_index > lastBwDBar and high >= bwdZoneBot and low <= bwdZoneTop

// ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
//  MODE + BIAS
//  Most recent event between sweep and BwD determines mode
//  REVERSAL mode  ΓåÆ from sweep
//  CONTINUATION mode ΓåÆ from BwD
// ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
barsSweep = na(lastSweepBar) ? 99999 : bar_index - lastSweepBar
barsBwD   = na(lastBwDBar)   ? 99999 : bar_index - lastBwDBar

string mode = "WAIT"
string bias = "NEUTRAL"

if lastSweepType == "NONE" and lastBwDType == "NONE"
    // no events yet ΓÇö stay in WAIT
    mode := "WAIT"
    bias := "NEUTRAL"
else if barsSweep <= barsBwD and lastSweepType != "NONE"
    if lastSweepType == "BSL"
        mode := "REVERSAL"
        bias := "SHORT"
    else if lastSweepType == "SSL"
        mode := "REVERSAL"
        bias := "LONG"
else if lastBwDType != "NONE"
    if lastBwDType == "BULL"
        mode := "CONTINUATION"
        bias := "LONG"
    else if lastBwDType == "BEAR"
        mode := "CONTINUATION"
        bias := "SHORT"

aboveEq = not na(eq) and close >  eq
belowEq = not na(eq) and close <= eq

// draw target
string drawTarget   = "ΓÇö"
float  drawTargetPx = na

if mode == "REVERSAL"
    if bias == "SHORT"
        drawTarget   := aboveEq ? "IRL  ┬╖  Equilibrium 50%" : "ERL Low  ┬╖  SSL Pool"
        drawTargetPx := aboveEq ? eq : rangeLo
    else
        drawTarget   := belowEq ? "IRL  ┬╖  Equilibrium 50%" : "ERL High  ┬╖  BSL Pool"
        drawTargetPx := belowEq ? eq : rangeHi

else if mode == "CONTINUATION"
    if inBwDZone
        drawTarget   := "ΓÜí Displacement Zone  ┬╖  Entry Here"
        drawTargetPx := (bwdZoneTop + bwdZoneBot) / 2.0
    else if bias == "LONG"
        // post-bullish-BwD: target is the new extension high (where fresh BSL is forming)
        drawTarget   := "Extension High  ┬╖  New BSL Forming"
        drawTargetPx := extensionHi
    else
        // post-bearish-BwD: target is the new extension low (where fresh SSL is forming)
        drawTarget   := "Extension Low  ┬╖  New SSL Forming"
        drawTargetPx := extensionLo

// ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
//  CONFIDENCE SCORE  (0ΓÇô100)
//
//  Base event           ΓåÆ +35
//  PDH/PDL confluence   ΓåÆ +15
//  Session active       ΓåÆ +20  (off session: ΓêÆ10)
//  BwD retrace in zone  ΓåÆ +20
//  Event freshness      ΓåÆ up to +20
//  Range formed         ΓåÆ +10
// ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
int score = 0

// base event
if mode == "REVERSAL"    and lastSweepType != "NONE"
    score += 35
if mode == "CONTINUATION" and lastBwDType  != "NONE"
    score += 35

// PDH/PDL confluence ΓÇö only check the level relevant to the current event
if not na(pdh) and not na(pdl) and mode != "WAIT"
    eventLvl = mode == "REVERSAL" ? (lastSweepType == "BSL" ? bslSweptLvl : sslSweptLvl) : (lastBwDType == "BULL" ? bwdZoneTop : bwdZoneBot)
    keyLvl   = mode == "REVERSAL" ? (lastSweepType == "BSL" ? pdh : pdl) : (lastBwDType == "BULL" ? pdh : pdl)
    if not na(eventLvl) and not na(keyLvl) and math.abs(eventLvl - keyLvl) < atr * 1.5
        score += 15

// session
if sessionOn
    score += inSess ? 20 : -10

// BwD zone retrace ΓÇö price is back in the entry zone
if mode == "CONTINUATION" and inBwDZone
    score += 20

// freshness
freshBars = mode == "REVERSAL" ? barsSweep : barsBwD
score     += freshBars < 20 ? 20 : freshBars < 50 ? 12 : freshBars < 100 ? 6 : 0

// range
if not na(rangeHi) and not na(rangeLo)
    score += 10

score := math.max(0, math.min(score, 100))

// ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
//  FVG  ΓÇö  IRL INEFFICIENCIES
// ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
type FVG
    float top
    float bot
    int   barIdx
    bool  bullish
    bool  mitigated
    box   bx
    label lbl

var array<FVG> fvgs = array.new<FVG>()

if fvgOn and barstate.isconfirmed
    bullGap = low  > high[2] and (low  - high[2]) > atr * fvgMinATR
    bearGap = high < low[2]  and (low[2] - high)  > atr * fvgMinATR
    if bullGap
        array.push(fvgs, FVG.new(low, high[2], bar_index, true,  false, na, na))
    if bearGap
        array.push(fvgs, FVG.new(low[2], high, bar_index, false, false, na, na))

if array.size(fvgs) > 0
    for i = 0 to array.size(fvgs) - 1
        f = array.get(fvgs, i)
        if not f.mitigated
            if f.bullish  and low  <= f.bot  then f.mitigated := true
            if not f.bullish and high >= f.top then f.mitigated := true

while array.size(fvgs) > fvgMax
    old = array.shift(fvgs)
    if not na(old.bx)  then box.delete(old.bx)
    if not na(old.lbl) then label.delete(old.lbl)

// ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
//  DRAW  ΓÇö  ERL / IRL LINES
// ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
var line  lnHi = na,  lnLo = na,  lnEq = na
var label lbHi = na,  lbLo = na,  lbEq = na

if barstate.islast
    line.delete(lnHi),  line.delete(lnLo),  line.delete(lnEq)
    label.delete(lbHi), label.delete(lbLo), label.delete(lbEq)

    if showERL and not na(rangeHi)
        lnHi := line.new(rangeHiBar, rangeHi, bar_index + extR, rangeHi,
                  color = cERLHi, width = 2)
        lbHi := label.new(bar_index + extR, rangeHi,
                  "Γùñ  ERL HIGH  ┬╖  BUY STOPS (BSL)  ┬╖  " + str.tostring(rangeHi, format.mintick),
                  color = color.new(cERLHi, 85), textcolor = cERLHi,
                  style = label.style_label_left, size = size.small)

    if showERL and not na(rangeLo)
        lnLo := line.new(rangeLoBar, rangeLo, bar_index + extR, rangeLo,
                  color = cERLLo, width = 2)
        lbLo := label.new(bar_index + extR, rangeLo,
                  "Γùú  ERL LOW  ┬╖  SELL STOPS (SSL)  ┬╖  " + str.tostring(rangeLo, format.mintick),
                  color = color.new(cERLLo, 85), textcolor = cERLLo,
                  style = label.style_label_left, size = size.small)

    if showIRL and not na(eq)
        lnEq := line.new(math.min(rangeHiBar, rangeLoBar), eq, bar_index + extR, eq,
                  color = cIRL, width = 1, style = line.style_dashed)
        lbEq := label.new(bar_index + extR, eq,
                  "Γùå  IRL  ┬╖  EQUILIBRIUM 50%  ┬╖  " + str.tostring(eq, format.mintick),
                  color = color.new(cIRL, 85), textcolor = cIRL,
                  style = label.style_label_left, size = size.small)

