var line  lnPDH = na,  lnPDL = na
var label lbPDH = na,  lbPDL = na

if showPD and barstate.islast
    line.delete(lnPDH), line.delete(lnPDL)
    label.delete(lbPDH), label.delete(lbPDL)

    if not na(pdh)
        lnPDH := line.new(dayStartBar, pdh, bar_index + extR, pdh,
                   color = cPDH, width = 1, style = line.style_dotted)
        if pdLabel
            lbPDH := label.new(bar_index + extR, pdh,
                       "Γû▓  PDH  ┬╖  " + str.tostring(pdh, format.mintick),
                       color = color.new(cPDH, 85), textcolor = cPDH,
                       style = label.style_label_left, size = size.small)

    if not na(pdl)
        lnPDL := line.new(dayStartBar, pdl, bar_index + extR, pdl,
                   color = cPDL, width = 1, style = line.style_dotted)
        if pdLabel
            lbPDL := label.new(bar_index + extR, pdl,
                       "Γû╝  PDL  ┬╖  " + str.tostring(pdl, format.mintick),
                       color = color.new(cPDL, 85), textcolor = cPDL,
                       style = label.style_label_left, size = size.small)

