//  DRAW  ΓÇö  BwD DISPLACEMENT ZONE
//  Box drawn on the body of the break candle
//  Extends right ΓÇö this is the retrace entry area
// ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
var box   bwdBox = na
var label bwdLbl = na

if showBwDZone
    if bullBwD or bearBwD
        box.delete(bwdBox)
        label.delete(bwdLbl)
        zClr  = bullBwD ? cBwDBull : cBwDBear
        zDir  = bullBwD ? "BULL BwD" : "BEAR BwD"
        zStyle = bullBwD ? label.style_label_lower_right : label.style_label_upper_right
        bwdBox := box.new(bar_index, bwdZoneTop, bar_index + bwdZoneExt, bwdZoneBot,
                   border_color = color.new(zClr, 20),
                   bgcolor      = color.new(zClr, 78),
                   border_width = 2)
        bwdLbl := label.new(bar_index, bullBwD ? bwdZoneTop : bwdZoneBot,
                   "ΓÜí  " + zDir + "  ┬╖  RETRACE ENTRY ZONE",
                   color = color.new(zClr, 75), textcolor = zClr,
                   style = zStyle, size = size.small)
    else if not na(bwdBox)
        box.set_right(bwdBox, bar_index + bwdZoneExt)

// ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
//  DRAW  ΓÇö  FLIPPED LEVEL
//  The ERL that got broken is redrawn as dashed ΓÇö now acts as IRL (S or R)
// ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
var line  lnFlip = na
var label lbFlip = na

if showFlipped and barstate.islast
    line.delete(lnFlip)
    label.delete(lbFlip)
    if not na(flippedLvl)
        flipRole = flippedBull ? "NOW SUPPORT" : "NOW RESISTANCE"
        lnFlip := line.new(na(lastBwDBar) ? bar_index - 10 : lastBwDBar,
                    flippedLvl, bar_index + extR + 15, flippedLvl,
                    color = cFlipClr, width = 1, style = line.style_dashed)
        lbFlip := label.new(bar_index + extR + 15, flippedLvl,
                    "Γå╗  FLIPPED  ┬╖  " + flipRole + "  ┬╖  " + str.tostring(flippedLvl, format.mintick),
                    color = color.new(cFlipClr, 82), textcolor = cFlipClr,
                    style = label.style_label_left, size = size.tiny)

// ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
//  DRAW  ΓÇö  FVG BOXES (IRL INEFFICIENCIES)
// ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
if showFVGVis and array.size(fvgs) > 0
    for i = 0 to array.size(fvgs) - 1
        f = array.get(fvgs, i)
        if not f.mitigated
            if na(f.bx)
                f.bx  := box.new(f.barIdx - 1, f.top, bar_index + 5, f.bot,
                          border_color = color.new(cFVGClr, 40),
                          bgcolor      = color.new(cFVGClr, 82),
                          border_width = 1)
                f.lbl := label.new(f.barIdx, f.bullish ? f.top : f.bot,
                          "IRL ┬╖ FVG",
                          color = color.new(cFVGClr, 80), textcolor = cFVGClr,
                          style = label.style_label_right, size = size.tiny)
            else
                box.set_right(f.bx, bar_index + 5)
        else
            if not na(f.bx)  then box.delete(f.bx)
            if not na(f.lbl) then label.delete(f.lbl)
            f.bx  := na
            f.lbl := na

