plotshape(showMarkers and bslSweep, "BSL Swept",   shape.triangledown, location.abovebar,
     color = cERLHi,   size = size.small,  text = "BSL\nSWEPT", textcolor = cERLHi)
plotshape(showMarkers and sslSweep, "SSL Swept",   shape.triangleup,   location.belowbar,
     color = cERLLo,   size = size.small,  text = "SSL\nSWEPT", textcolor = cERLLo)
plotshape(showMarkers and bullBwD,  "Bull BwD",    shape.arrowup,      location.belowbar,
     color = cBwDBull, size = size.normal, text = "BwD Γåæ",      textcolor = cBwDBull)
plotshape(showMarkers and bearBwD,  "Bear BwD",    shape.arrowdown,    location.abovebar,
     color = cBwDBear, size = size.normal, text = "BwD Γåô",      textcolor = cBwDBear)

// ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
//  ADVISOR PANEL
// ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
if showPanel and barstate.islast
    var table tbl = table.new(position.top_right, 2, 15,
         bgcolor      = cBgDeep,
         border_color = cPurple,
         border_width = 1,
         frame_color  = cPurple,
         frame_width  = 2)

    // ΓöÇΓöÇ HEADER ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
    table.cell(tbl, 0, 0, "ΓùóΓùñ  ERL ΓåÆ IRL ENGINE v2  ΓùÑΓùú",
         text_color = cCyan, text_size = size.normal,
         bgcolor    = color.new(cPurple, 60))
    table.merge_cells(tbl, 0, 0, 1, 0)

    // ΓöÇΓöÇ MODE ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
    modeClr = mode == "REVERSAL" ? cAmber : mode == "CONTINUATION" ? cCyan : cDim
    table.cell(tbl, 0, 1, "  MODE",      text_color = cTextMute, text_size = size.small,
         text_halign = text.align_left,  bgcolor = cBgPanel)
    table.cell(tbl, 1, 1, mode + "  ",   text_color = modeClr,   text_size = size.normal,
         text_halign = text.align_right, bgcolor = cBgPanel)

    // ΓöÇΓöÇ BIAS ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
    biasClr = bias == "LONG" ? cGreen : bias == "SHORT" ? cRed : cDim
    table.cell(tbl, 0, 2, "  BIAS",      text_color = cTextMute, text_size = size.small,
         text_halign = text.align_left,  bgcolor = cBgRow)
    table.cell(tbl, 1, 2, bias + "  ",   text_color = biasClr,   text_size = size.normal,
         text_halign = text.align_right, bgcolor = cBgRow)

    // ΓöÇΓöÇ LAST EVENT ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
    evtStr = mode == "REVERSAL" ? (lastSweepType == "BSL" ? "BSL Raided" : "SSL Raided") : mode == "CONTINUATION" ? (lastBwDType == "BULL" ? "Bull BwD" : "Bear BwD") : "None"
    evtClr = mode == "REVERSAL" ? cAmber : cCyan
    table.cell(tbl, 0, 3, "  LAST EVENT", text_color = cTextMute, text_size = size.small,
